"""Presentación HTML local. Texto y cifras se derivan de los reportes cerrados."""
import json
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parents[3];PERF=ROOT/'tests/performance'
def table(h,rs):return '<div class="scroll"><table><tr>'+''.join('<th>'+str(x)+'</th>'for x in h)+'</tr>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>'for x in r)+'</tr>'for r in rs)+'</table></div>'
def p(s):return '<p>'+s+'</p>'
def command(a):return '<div class="cmd"><button class="copy">Copiar</button><pre><code>'+escape("Set-Location 'C:\\Users\\Franco\\qolqe-g4-qa'\npowershell -NoProfile -ExecutionPolicy Bypass -File scripts/performance.ps1 "+a)+'</code></pre></div>'
def fmt(v):return 'sin muestra'if v is None else f'{v:.2f}'if isinstance(v,float)else str(v)
def main():
 results=json.loads((PERF/'resultados/resumen-entrega.json').read_text(encoding='utf-8'));by={r['profile']:r for r in results};primary=[by[k]for k in ['carga','campana','estres']if k in by]
 slides=[]
 def add(title,text,label='QUINCENA QOLQE · PARTE 3'):slides.append((title,text,label))
 add('¿Qolqe soporta la campaña de quincena?', '<div class="lead">Pruebas de rendimiento · Granit y Franco · Grupo 4</div>'+p('Evaluamos la capacidad de Qolqe Wallet frente a la demanda normal y la campaña. Combinamos un modelo de carga derivado del negocio, medición de recursos y conciliación de operaciones monetarias.')+p('Las conclusiones corresponden al entorno local medido. Conservamos intacto el código original de la aplicación y registramos las limitaciones junto a cada resultado.'),'APERTURA')
 add('El requerimiento define qué comprobar',p('En hora punta se inician 3000 sesiones por hora. Cada sesión dura en promedio dos minutos y realiza seis operaciones. La campaña triplica los usuarios simultáneos durante quince minutos y concentra inicios en los primeros cinco.')+table(['Condición','Criterio'],[['Consultas e inicio de sesión','p95 menor que 800 ms'],['Transferencias, recargas y pagos','p95 menor que 1500 ms'],['Hora punta','Como máximo 1% de errores y sin acumular retrasos'],['Campaña','Ninguna operación monetaria parcial ni duplicada']])+p('“Degradación razonable” no define un umbral numérico de campaña. Los tiempos de campaña se compararon con la referencia normal; el requerimiento no fija un SLA numérico para ese periodo.'),'NEGOCIO')
 add('Herramienta utilizada: k6',p('Utilizamos k6 como único generador de carga y evaluamos Locust y JMeter como alternativas.')+p('k6 permite definir escenarios como código, aplicar etiquetas por operación y conservar métricas y umbrales. Lo elegimos por su integración con scripts versionados y su cercanía con JavaScript/TypeScript ya usado por el equipo.')+p('En Qolqe, los scripts reúnen las peticiones HTTP, las pausas y la mezcla de operaciones; la configuración define los VUs y las rampas. Los umbrales distinguen consultas y operaciones de dinero. Esto permite reproducir carga normal, campaña y estrés a partir del mismo flujo.')+p('Implementamos la preparación de datos, la medición de CPU y memoria y la conciliación monetaria con Python. psutil funciona como monitor de recursos; no es un segundo generador de carga.'),'HERRAMIENTA')
 add('Por qué se eligió k6 frente a las alternativas',table(['Herramienta','Cuándo resulta conveniente','Decisión para Qolqe'],[['k6 · seleccionada','Pruebas HTTP definidas en JavaScript, con etapas, etiquetas y umbrales en el código.','El equipo ya utiliza JavaScript/TypeScript. Se mantuvieron los escenarios en un lenguaje conocido y se configuraron tres perfiles sobre el mismo flujo.'],['Locust · alternativa','Equipos que modelan usuarios con Python y necesitan reutilizar bibliotecas o lógica de ese ecosistema.','Se prefirió JavaScript para los escenarios y se reservó Python para datos, monitoreo y análisis. Locust no se utilizó en las ejecuciones.'],['JMeter · alternativa','Diseño visual de planes y pruebas que combinan protocolos, como HTTP y JDBC.','El alcance se centró en HTTP; se priorizaron scripts JavaScript frente a mantener un plan visual adicional. JMeter no se utilizó en las ejecuciones.']])+p('La elección de k6 respondió al lenguaje del equipo, el alcance HTTP de la prueba y la configuración de carga y umbrales mediante código.'),'COMPARACIÓN')
 add('Los flujos se priorizan por frecuencia y riesgo',table(['Operación','Peso','Justificación'],[['Saldo y perfil','30%','Acceso frecuente a información de cuenta'],['Movimientos','15%','Consulta de historial y confirmación de operaciones'],['Transferencias','15%','Movimiento directo de dinero'],['Contactos','10%','Consulta y búsqueda usadas en transferencias'],['Recargas','10%','Débito y emisión de comprobante'],['Consulta de deudas','6%','Consulta previa al pago'],['Pagos','4%','Débito y cancelación de una deuda'],['Otros','10%','Límites, alertas, solicitudes, dispositivos y sesiones']])+p('Las ponderaciones se aplican a operaciones de negocio. Saldo y perfil agrupa dos peticiones HTTP; login se mide por separado. El reporte conserva la mezcla realmente obtenida.'),'ALCANCE')
 add('El modelo parte de los datos del negocio',table(['Parámetro','Derivación'],[['Concurrencia normal','3000/60 × 2 = aproximadamente 100 usuarios'],['Concurrencia de campaña','100 × 3 = aproximadamente 300 usuarios'],['Volumen normal','3000 × 6 / 3600 = 5 operaciones/s, además de login'],['Pausas','10–25 s; triangular con moda 19 s para media 18 s'],['Sesión','Un login y seis operaciones; no se fuerza a durar exactamente 120 s']])+p('La duración de sesión de dos minutos es una media de negocio. Bajo degradación, las sesiones pueden durar más. Los percentiles y el throughput se miden en ventanas estables y las diferencias se registran.'),'MODELO')
 add('Carga, campaña y estrés se ejecutan por separado',table(['Perfil','Configuración','Objetivo'],[['Referencia','1 usuario','Validar scripts y obtener una referencia sin carga'],['Carga','Subida 300 s → 100 VUs; 600 s estable; descenso 60 s','Comprobar el horario punta'],['Campaña','Subida 300 s → 300 VUs; 600 s estable; descenso 60 s','Representar quince minutos con concentración inicial'],['Estrés','25 → 50 → 100 → 200 → 300 → 450 → 600 VUs; 150 s estables por escalón','Localizar incumplimiento observado']])+p('Las rampas de cinco minutos de campaña provienen del requerimiento. Las duraciones estables de carga y los escalones de estrés son decisiones experimentales justificadas. Las sesiones pueden finalizar durante una gracia adicional de hasta 150 s.'),'ESCENARIOS')
 add('Datos independientes evitan falsos fallos de rendimiento',p('Cada VU tiene credenciales exclusivas, un destinatario y saldo inicial suficiente. Se generan mil movimientos de historial por propietario, contactos y deudas pendientes suficientes. Las consultas de deudas usan una deuda reservada que no se consume en pagos.')+p('Las transferencias y pagos utilizan S/1; las recargas S/5 y números distintos. Esto reduce el riesgo de agotar saldo, límites diarios o recargas por número. La preparación ocurre antes de la medición y no se modifican saldos durante la carga.')+p('Cada ejecución utilizó una base independiente y el código original de Qolqe.')+'<aside>Los rechazos por reglas de negocio se clasifican por separado de los errores de servidor y los timeouts.</aside>','DATOS')
 add('Los umbrales se evalúan junto con la integridad',p('Calculamos percentiles por operación para que un endpoint lento no quede oculto por otros rápidos. Comparamos el volumen completado con la demanda normal y registramos errores HTTP, de transporte y de datos.')+p('La verificación monetaria relaciona cada intento con su respuesta, registro de operación, movimientos y saldos finales de propietario y destinatario. Un timeout no demuestra que la operación no se haya aplicado: se consulta la evidencia persistida.')+p('No reintentamos automáticamente escrituras de dinero. El criterio de integridad de campaña exige cero operaciones parciales y cero duplicados.'),'ACEPTACIÓN')
 add('CPU y memoria se miden en ambos procesos',p('El monitor registra cada segundo CPU y memoria de Qolqe y de k6. En Windows se incluye el proceso hijo de Python donde se ejecuta la aplicación. Las marcas de tiempo permiten cruzar recursos con latencia, errores y throughput.')+p('La CPU se conserva en equivalentes de núcleo y normalizada al total de procesadores. RSS se expresa en MB. Se registra también el estado del host para reconocer competencia de otros procesos.')+p('Si el generador supera aproximadamente 80% de CPU total, la corrida se considera inválida. Una ejecución válida puede incumplir el SLA del producto. La laptop compartida no certifica capacidad de producción.'),'ENTORNO')
 add('Demostración en vivo con un perfil breve',p('Ejecutamos una prueba breve con cinco usuarios virtuales para demostrar la automatización y generar evidencia nueva. Conservamos las pausas del modelo; la terminal muestra el usuario, la operación, su estado HTTP y duración.')+command('demo')+command('open')+p('El ejecutor prepara los datos y levanta Qolqe. k6 genera las operaciones HTTP, mientras el monitor registra los recursos. Al cierre se comparan saldos y movimientos con las operaciones realizadas.')+p('Con esta demo demostramos que el flujo se ejecuta y produce un reporte nuevo. Para evaluar el requerimiento utilizamos los experimentos completos de carga, campaña y estrés, conservados en sus reportes.'),'DEMO')
 demo=by.get('demo')
 if demo:
  dw=demo['windows'][0];di=demo['integrity'];dr=demo['resources'];dbase='../../tests/performance/resultados/'+demo['meta']['run_id']
  demo_rows=[[op,demo['by_operation'][op]['count'],fmt(demo['by_operation'][op]['p95']),limit]for op,limit in [('movimientos',800),('login',800),('transferencias',1500)]]
  demo_body=p(f"Demo documentada: {demo['meta']['run_id']}. Estas cifras pertenecen a esa ejecución; cada nueva corrida genera sus propias mediciones.")
  demo_body+=table(['Operación','Muestras','p95 ms','Referencia ms'],demo_rows)
  demo_body+=p(f"En la ventana estable de {dw['start_s']} a {dw['end_s']} s completamos {dw['operations']} operaciones de negocio; el throughput fue de {dw['ops_s']:.3f} operaciones correctas/s y el error fue de {100*dw['error_rate']:.1f}%. La demo no representa los 100 usuarios de hora punta ni emite una aprobación del SLA completo.")
  demo_body+='<details><summary>Percentiles, mezcla y medición de login</summary>'+p('p50 es la mediana; p95 y p99 describen los tiempos que cubren aproximadamente el 95% y el 99% de las muestras. Con pocas observaciones, estos valores describen la demo y no permiten estimar de forma sólida el comportamiento a gran escala.')+p('La distribución observada varía porque seleccionamos operaciones aleatoriamente y la demo es corta. Login sí tiene muestras de tiempo; su distribución figura como «sin muestra» porque no participa en la mezcla de negocio.')+'</details>'
  demo_body+='<details><summary>Recursos e integridad monetaria</summary>'+table(['Medición','Resultado'],[['CPU máxima Qolqe, % del host',fmt(dr['app_cpu_host_max'])],['CPU máxima k6, % del host',fmt(dr['generator_cpu_host_max'])],['RSS máxima Qolqe, MB',fmt(dr['app_rss_mb_max'])],['Muestras del monitor',dr['samples']]])+p(f"Conciliamos la corrida completa: {di['attempts']} intentos monetarios, {di['database_operations']} operaciones persistidas y {len(di['issues'])} anomalías detectadas. Esta verificación incluye las etapas fuera de la ventana estable; no equivale al número de operaciones de la tabla anterior.")+'</details>'
  demo_body+=p(f'<a target="_blank" href="{dbase}/reporte.html">Abrir reporte de la demo documentada</a> · <a target="_blank" href="../../tests/performance/resultados/index.html">Índice y última demo disponible</a>')
  add('Cómo interpretamos el reporte de la demo',demo_body,'REPORTE DE DEMO')
 rows=[]
 for r in primary:
  w=r['windows'][0]
  if r['profile']=='estres':rows.append(['Estrés','25–600','Por escalón','Por escalón','0–100','Degradación en niveles altos'])
  else:
   outcome=('Cumple SLA normal'if r['approved']else'Incumple latencia de movimientos')if r['profile']=='carga'else('Integridad monetaria cumplida'if r['integrity']['approved']else'Incidencias monetarias')
   rows.append(['Carga'if r['profile']=='carga'else'Campaña',r['meta']['target_vus'],fmt(w['ops_s']),fmt(r['by_operation']['movimientos']['p95']),fmt(100*w['error_rate']),outcome])
 add('Resultados observados en el entorno local',table(['Perfil','VUs','Operaciones correctas/s','p95 movimientos ms','Error negocio %','Resultado'],rows)+p('Con 100 usuarios superamos el volumen normal de 5 operaciones/s, pero movimientos excedió el límite de 800 ms. En campaña conservamos la integridad monetaria y observamos latencia superior a la referencia normal.')+table(['Estado del reporte','Interpretación'],[['Válida','Reunimos evidencia y controles técnicos para analizar la corrida; no implica cumplimiento del producto.'],['Cumple perfil','Evaluamos los criterios de cada experimento. En demo y referencia aparece None porque no emitimos aceptación de carga completa.'],['Integridad','Conciliamos registros, movimientos y saldos. True significa que no detectamos anomalías en las verificaciones realizadas.']])+'<p><a target="_blank" href="../../tests/performance/resultados/index.html">Abrir todos los reportes</a> · <a target="_blank" href="../../docs/parte3/Informe_Rendimiento_Qolqe.docx">Informe de rendimiento</a></p>','RESULTADOS')
 for profile,title in [('carga','Hora punta: resultado y evolución'),('campana','Campaña: respuesta e integridad'),('estres','Estrés: dónde dejó de cumplir')]:
  r=by.get(profile)
  if not r:continue
  base='../../tests/performance/resultados/'+r['meta']['run_id']
  breaches=[[op,fmt(v['p95']),1500 if op in ['transferencias','recargas','pagos']else 800]for op,v in r['by_operation'].items()if v['p95']>=(1500 if op in ['transferencias','recargas','pagos']else 800)]
  detail=table(['Operación que supera el umbral normal','p95 ms','Límite ms'],breaches)if breaches else p('Los p95 por operación de las ventanas analizadas están dentro de la referencia temporal normal.')
  explanation=''
  if profile=='carga':
   explanation=p(f"Con 100 usuarios completamos {r['windows'][0]['ops_s']:.2f} operaciones correctas/s y registramos {100*r['windows'][0]['error_rate']:.0f}% de errores. Sostuvimos el volumen requerido, pero movimientos alcanzó p95 de {r['by_operation']['movimientos']['p95']:.2f} ms frente a 800 ms: el perfil no cumplió todos los criterios.")
   explanation+=p(f"El p95 agregado de consultas fue de {r['windows'][0]['p95_consulta']:.2f} ms. Las consultas rápidas ocultan parte del efecto de movimientos; por eso fundamentamos la decisión en cada operación y no solamente en el agregado.")
  elif profile=='campana':
   explanation=p(f"Con 300 usuarios completamos {r['windows'][0]['ops_s']:.2f} operaciones correctas/s y conciliamos {r['integrity']['database_operations']} operaciones monetarias de la corrida completa sin anomalías detectadas.")
   explanation+=p(f"El perfil figura como cumplido por su validez e integridad obligatoria. No equivale a cumplir los tiempos normales: movimientos registró p95 de {r['by_operation']['movimientos']['p95']:.2f} ms frente a la referencia de 800 ms. El requerimiento no cuantifica la degradación temporal admisible en campaña.")
  else:
   explanation=p('Al aumentar usuarios observamos mayor latencia y, desde 450, errores de servicio y una caída del throughput exitoso. Estas señales juntas muestran degradación: evaluamos cuántas operaciones finalizaron correctamente, además de los intentos realizados.')
   explanation+=p('Los tiempos cercanos a 30 s reflejan el timeout de una petición. Saldo/perfil agrupa dos peticiones secuenciales y puede aproximarse a 60 s. Esas duraciones no implican respuestas exitosas.')
  reading='<details><summary>Cómo leemos este gráfico</summary>'+p('El eje horizontal muestra segundos. Calculamos p95 por intervalos de 15 s y sombreamos las ventanas estables. Las líneas discontinuas marcan 800 ms para consultas y 1500 ms para dinero; los intervalos sin muestras no tienen un p95 calculable.')+p('El gráfico de errores incluye login; las tablas separan sus errores de los de negocio. El throughput cuenta operaciones de negocio correctas. Los VUs se leen en su propio eje. CPU y RSS muestran consumo, pero un aumento de memoria aislado no demuestra una fuga y una CPU baja no descarta bloqueos.')+'</details>'
  add(title,p(f"Ejecución {r['meta']['run_id']}. Integridad monetaria: {'conforme' if r['integrity']['approved'] else 'con incidencias'}.")+explanation+detail+reading+f'<img alt="Evolución de latencia, errores, throughput, usuarios y recursos" src="{base}/graficos/evolucion.png">'+p(f'<a target="_blank" href="{base}/reporte.html">Abrir reporte de esta corrida</a> · <a target="_blank" href="{base}/integridad.json">Conciliación</a> · <a target="_blank" href="{base}/recursos.csv">Recursos CSV</a>'),'EVIDENCIA')
 diagnosis=json.loads((PERF/'resultados/diagnostico-sql.json').read_text(encoding='utf-8'))if(PERF/'resultados/diagnostico-sql.json').exists()else None
 diagtext=''
 if diagnosis:
  diagtext=table(['Movimientos en historial','Consultas SELECT','Consultas SUM','Mediana ms (diagnóstico directo)'],[[r['historial'],r['selects'],r['sumas'],fmt(r['mediana_ms'])]for r in diagnosis['summary']])+p('El patrón N+1 del historial está confirmado: una consulta adicional por movimiento antes de paginar. En estrés también se registran bloqueos de SQLite durante escrituras. Son focos distintos; no se atribuyen todos los bloqueos al N+1.')+'<p><a target="_blank" href="../../tests/performance/resultados/diagnostico-sql.json">Abrir diagnóstico SQL</a></p>'
 add('Diagnóstico y límites de las conclusiones',diagtext+p('La consulta de movimientos incumplió el tiempo objetivo en carga normal. Desde 450 usuarios se registraron errores HTTP 500 y timeouts, junto con mensajes database is locked durante escrituras.')+p('Los bloqueos de escritura y el patrón N+1 son factores de degradación observados. No se midió por separado la contribución del disco, la espera de ejecución o la duración de los bloqueos.')+p('El mayor nivel probado que cumplió la referencia temporal y el volumen proporcional fue de 50 usuarios. El siguiente nivel, 100, incumplió la latencia de movimientos.'),'ANÁLISIS')
 stress=by.get('estres')
 if stress:
  levels=[25,50,100,200,300,450,600];rows=[]
  for level,w in zip(levels,stress['windows']):rows.append([level,fmt(w['ops_s']),fmt(w['by_operation'].get('movimientos',{}).get('p95')),fmt(100*w['error_rate'])if w['error_rate']is not None else '—','Sí'if w.get('per_operation_ok')and w['ops_s']>=level*.05 else 'No'])
  add('Capacidad observada y riesgo de respuestas perdidas',table(['VUs','Operaciones correctas/s','p95 movimientos ms','Error negocio %','Cumple referencia y volumen'],rows)+p('El mayor nivel probado que cumplió fue de 50 usuarios; el siguiente, 100, incumplió. Acotamos la capacidad observada entre ambos para ventanas de 150 s y este entorno local; no determinamos un máximo exacto de producción.')+p(f"En estrés se conciliaron {stress['integrity']['committed_after_http_error']} operaciones persistidas aunque el cliente recibiera error o perdiera la respuesta. No detectamos duplicados ni operaciones parciales, pero existe riesgo de repetición manual. Recomendamos consulta de estado e idempotencia; no implementamos esas mejoras en Qolqe."),'ANÁLISIS')
 add('Resistencia, recomendaciones y cierre',p('La operación de 6:00 a 24:00 hace relevante una prueba de resistencia de 18 horas. No se ejecutó esa validación completa por la ventana experimental y el uso de una laptop compartida. La estabilidad durante una jornada completa y las posibles fugas de memoria no fueron evaluadas.')+p('Se propone aislar servidor y generador, instrumentar base de datos y transacciones, repetir el punto cercano al límite y acordar qué degradación numérica se admite durante campaña.')+p('La carga normal superó el volumen requerido, pero incumplió la latencia de movimientos. La campaña conservó la integridad monetaria. El estrés mostró degradación temporal desde 100 usuarios y fallos de servicio desde 450.'),'CIERRE')
 add('Comandos y carpetas para consultar',command('report')+command('open')+p('Ejecuciones completas: usar carga, campana y estres en lugar de report; se ejecutan de una en una. La acción all realiza referencia y los tres perfiles.')+'<pre>tests/performance/escenarios/       → acciones HTTP\ntests/performance/configuracion/   → modelo y umbrales\ntests/performance/resultados/      → evidencia por ejecución\ndocs/parte3/                       → informe\napidoc/parte3/                     → esta presentación</pre>'+p('Servidor local de consulta: .venv/Scripts/python.exe -m http.server 8765 --bind 127.0.0.1 · Presentación: http://localhost:8765/apidoc/parte3/.'),'ANEXO OPERATIVO')
 add('Anexo / Referencias','<ul><li><a target="_blank" href="https://github.com/granitespinoza/qolqe-g4-qa/tree/parte-3">Repositorio de entrega · tag parte-3</a></li><li><a target="_blank" href="../../tests/performance/resultados/index.html">Reportes y evidencias de Parte 3</a></li><li><a target="_blank" href="../../tests/performance/README.md">Ejecución y decisiones del modelo</a></li><li><a target="_blank" href="../../docs/parte3/Informe_Rendimiento_Qolqe.docx">Informe de rendimiento</a></li><li><a target="_blank" href="https://grafana.com/docs/k6/latest/using-k6/scenarios/">Escenarios de k6</a> · <a target="_blank" href="https://grafana.com/docs/k6/latest/using-k6/thresholds/">Umbrales de k6</a></li></ul>'+p('Las evidencias corresponden a las ejecuciones locales identificadas en cada reporte.'))
 css='''*{box-sizing:border-box}:root{--ink:#22251f;--sage:#497a6a;--paper:#fafbf9}body{margin:0;background:var(--paper);color:var(--ink);font:20px/1.6 Segoe UI,Arial,sans-serif}header{position:sticky;top:0;z-index:4;background:#fafbf9f5;border-bottom:1px solid #dce2d9;display:flex;gap:12px;flex-wrap:wrap;align-items:center;justify-content:space-between;padding:12px 4vw}button,select{font:inherit;font-size:14px;border:1px solid #22251f;background:white;border-radius:7px;padding:8px 12px;cursor:pointer}nav{display:flex;align-items:center;gap:8px}main{max-width:1160px;margin:auto;padding:35px 30px 70px}.slide{padding:38px 48px;border:2px solid #22251f;border-radius:20px;background:white;box-shadow:5px 6px 0 #e9ebe6;min-height:650px}h1{font:500 clamp(30px,4vw,46px)/1.15 Georgia,serif;margin:20px 0 28px}p{margin:18px 0}.label{font-size:13px;letter-spacing:.12em;color:var(--sage);font-weight:700}.lead{font-size:24px;color:var(--sage)}table{width:100%;border-collapse:collapse;font-size:17px;margin:20px 0}td,th{padding:12px;border:1px solid #dce2d9;text-align:left;vertical-align:top}th{background:#ecd9a7}tr:nth-child(even){background:#fafbf9}.scroll{overflow:auto}aside{background:#eef4fa;border-left:4px solid #476f98;padding:20px}a{color:#285e52}img{max-width:100%;height:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:15px/1.6 Consolas,monospace;background:#edf5f1;padding:20px}details{margin:18px 0;border-top:1px solid #dce2d9;padding-top:12px}summary{cursor:pointer;font-weight:600;color:#285e52}details p{font-size:.94em}.cmd{position:relative}.copy{position:absolute;right:5px;top:5px;padding:3px 8px;font-size:12px}footer{text-align:center;font-size:14px;padding:20px;color:#626861}.all .slide{display:block!important;margin-bottom:30px}body.large{font-size:24px}body.large table{font-size:21px}:fullscreen{overflow:auto;background:#fafbf9}@media(max-width:700px){main{padding:12px}.slide{padding:22px;min-height:0}select{max-width:220px}header{position:static}}@media print{header,footer,.copy{display:none}details:not([open])>:not(summary){display:block!important}main{padding:0}.slide,.slide[hidden]{display:block!important;border:0;box-shadow:none;min-height:0;page-break-before:always}body{font-size:16px}h1{font-size:30px}table{font-size:13px}}'''
 js='''const slides=[...document.querySelectorAll('.slide')];let n=0;const jump=document.querySelector('#jump');function show(i){n=Math.max(0,Math.min(slides.length-1,i));slides.forEach((s,j)=>s.hidden=j!==n);jump.value=n;document.querySelector('#count').textContent=`${n+1}/${slides.length}`;history.replaceState(null,'','#'+(n+1));scrollTo(0,0)}document.querySelector('#prev').onclick=()=>show(n-1);document.querySelector('#next').onclick=()=>show(n+1);jump.onchange=()=>show(Number(jump.value));document.querySelector('#all').onclick=()=>document.body.classList.toggle('all');document.querySelector('#large').onclick=()=>document.body.classList.toggle('large');document.querySelector('#full').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();show(n+1)}if(e.key==='ArrowLeft'){e.preventDefault();show(n-1)}});document.querySelectorAll('.copy').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.parentElement.querySelector('code').textContent);b.textContent='Copiado'}catch(e){b.textContent='Seleccionar y copiar'}});show(Number(location.hash.slice(1))-1||0);'''
 opt=''.join(f'<option value="{i}">{i+1}. {escape(s[0])}</option>'for i,s in enumerate(slides));body=''.join(f'<section class="slide"{" hidden"if i else""}><div class="label">{s[2]}</div><h1>{s[0]}</h1>{s[1]}</section>'for i,s in enumerate(slides))
 out=ROOT/'apidoc/parte3';out.mkdir(parents=True,exist_ok=True);(out/'index.html').write_text('<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quincena Qolqe · Rendimiento</title><style>'+css+'</style></head><body><header><strong>QOLQE / ENTREGA 3</strong><select id="jump" aria-label="Elegir diapositiva">'+opt+'</select><nav><button id="prev" aria-label="Diapositiva anterior">←</button><span id="count"></span><button id="next" aria-label="Diapositiva siguiente">→</button><button id="all">Ver todo</button><button id="large">Letra +</button><button id="full">Pantalla completa</button></nav></header><main>'+body+'</main><footer>Flechas ← → para navegar · Desplazar para leer cada pantalla · Ctrl+P para PDF</footer><script>'+js+'</script></body></html>',encoding='utf-8');print('Presentación:',len(slides),'pantallas')
if __name__=='__main__':main()
